              <h3>Fast shipping</h3>
              <p>Orders leave the warehouse the same day.</p>
            </div>
          </div>
          <div class="card perk">
            <div class="card-body">
              <h3>Easy returns</h3>
              <p>Thirty days, no questions, free labels.</p>
            </div>
          </div>
