mkdir -p $TMPDIR/shots && cat > $TMPDIR/shoot.mjs <<'EOF'
import { chromium } from '@playwright/test';
const out = process.argv[2], port = process.env.PORT || 4173;
const b = await chromium.launch();
for (const [w,h,tag] of [[1280,800,'d'],[390,844,'m']]) {
  const p = await b.newPage({ viewport: { width: w, height: h } });
  p.on('console', m => console.log('console', m.text()));
  p.on('requestfailed', r => console.log('fail', r.url()));
  p.on('response', r => { if (r.status() >= 400) console.log('http', r.status(), r.url()); });
  for (const name of ['index','products','pricing','orders','about','contact']) {
    await p.goto(`http://127.0.0.1:${port}/${name}.html`);
    await p.evaluate(() => document.fonts.ready);
    const info = await p.evaluate(() => ({ sw: document.documentElement.scrollWidth, font: [...document.fonts].map(f=>f.family+':'+f.status).join(',') }));
    console.log(tag, name, JSON.stringify(info));
    await p.screenshot({ path: `${out}/${tag}-${name}.png`, fullPage: true });
  }
}
await b.close();
EOF
(node server.js & echo $! > $TMPDIR/pid; sleep 1; cp $TMPDIR/shoot.mjs ./.shoot.mjs; node ./.shoot.mjs $TMPDIR/shots; rm ./.shoot.mjs; kill $(cat $TMPDIR/pid))

