input.command:
cd /tmp/avb-secknz/project && cat > .probe.mjs <<'EOF'
import { chromium } from '@playwright/test';
const port = process.env.PORT;
const b = await chromium.launch(); const p = await b.newPage({viewport:{width:1280,height:800}});
await p.goto(`http://127.0.0.1:${port}/products.html`);
console.log(await p.evaluate(() => [...document.querySelectorAll('h3')].slice(0,2).map(e => { const s=getComputedStyle(e); return [e.textContent, s.fontWeight, s.fontSize, s.fontFamily].join('|'); })));
await p.goto(`http://127.0.0.1:${port}/pricing.html`);
console.log(await p.evaluate(() => [...document.querySelectorAll('h3,h2')].map(e => { const s=getComputedStyle(e); return [e.textContent.trim(), s.fontWeight, s.fontSize].join('|'); })));
await b.close();
EOF
(node server.js >/dev/null & sleep 1; node .probe.mjs; kill %1); rm .probe.mjs
